import React from "react";
import {
    COOL_POINTS_EARN_RULES,
    COOL_POINTS_LEVELS,
    COOL_POINTS_SPEND_RULES,
} from "../coolpoints/coolPointsConfig";
import { useCoolPoints } from "../coolpoints/useCoolPoints";

export default function CoolPointsDashboard() {
    const {
        balance,
        currentLevel,
        nextLevel,
        progress,
        lifetimeEarned,
        lifetimeSpent,
        transactions,
    } = useCoolPoints();

    return (
        <div className="cp-dashboard" data-testid="cool-points-dashboard">
            <div className="cp-dashboard-hero">
                <div>
                    <div className="cp-dashboard-label">HYPHSWORLD PASSPORT</div>
                    <div className="cp-dashboard-balance">{balance.toLocaleString()} CP</div>
                    <div className="cp-dashboard-rank">
                        Level {currentLevel.level} · {currentLevel.title}
                    </div>
                </div>

                <div className="cp-dashboard-stats">
                    <div>
                        <span>Lifetime Earned</span>
                        <strong>{lifetimeEarned.toLocaleString()} CP</strong>
                    </div>
                    <div>
                        <span>Lifetime Spent</span>
                        <strong>{lifetimeSpent.toLocaleString()} CP</strong>
                    </div>
                </div>
            </div>

            <div className="cp-progress-section">
                <div className="cp-progress-track large">
                    <div className="cp-progress-fill" style={{ width: `${progress.percent}%` }} />
                </div>
                <div className="cp-dashboard-next">
                    {nextLevel
                        ? `${progress.pointsNeeded.toLocaleString()} CP until Level ${nextLevel.level}: ${nextLevel.title}`
                        : "MAX LEVEL ACHIEVED"}
                </div>
            </div>

            <div className="cp-grid">
                <section className="cp-card">
                    <h3>LEVEL PROGRESSION</h3>
                    <ul>
                        {COOL_POINTS_LEVELS.map((level) => (
                            <li key={level.level} className={level.level === currentLevel.level ? "active" : ""}>
                                <strong>LVL {level.level}</strong>
                                <span>{level.title}</span>
                                <small>{level.reward}</small>
                            </li>
                        ))}
                    </ul>
                </section>

                <section className="cp-card">
                    <h3>WAYS TO EARN</h3>
                    <ul>
                        {COOL_POINTS_EARN_RULES.map((rule) => (
                            <li key={rule.id}>
                                <strong>+{rule.amount} CP</strong>
                                <span>{rule.label}</span>
                            </li>
                        ))}
                    </ul>
                </section>

                <section className="cp-card">
                    <h3>WAYS TO SPEND</h3>
                    <ul>
                        {COOL_POINTS_SPEND_RULES.map((rule) => (
                            <li key={rule.id}>
                                <strong>-{rule.cost} CP</strong>
                                <span>{rule.label}</span>
                            </li>
                        ))}
                    </ul>
                </section>
            </div>

            <section className="cp-card cp-activity-card">
                <h3>RECENT ACTIVITY</h3>

                {transactions.length === 0 ? (
                    <div className="cp-empty-state">
                        No transactions yet. Start stacking Cool Points.
                    </div>
                ) : (
                    <ul className="cp-activity-list">
                        {transactions.slice(0, 8).map((transaction) => (
                            <li key={transaction.id}>
                                <div>
                                    <strong>
                                        {transaction.type === "spend" ? "-" : "+"}
                                        {Math.abs(transaction.amount)} CP
                                    </strong>
                                    <span>{transaction.reason}</span>
                                </div>
                                <small>{transaction.sourceLabel}</small>
                            </li>
                        ))}
                    </ul>
                )}
            </section>
        </div>
    );
}
