import axios from "axios";

const CASH_RUN_GAME_KEY = "cash_run";

function resolveApiBase() {
    const configured = process.env.REACT_APP_BACKEND_URL?.trim();
    if (configured) {
        return `${configured.replace(/\/$/, "")}/api`;
    }

    if (typeof window !== "undefined" && window.location?.origin) {
        return `${window.location.origin}/api`;
    }

    return "/api";
}

export const API = resolveApiBase();

async function getSupabaseClient() {
    if (typeof window === "undefined" || !window.HWAuth?.getClient) return null;
    const client = await window.HWAuth.getClient();
    return client && typeof client.rpc === "function" ? client : null;
}

async function requireSupabaseSession(client) {
    const { data, error } = await client.auth.getSession();
    if (error) throw error;
    if (!data?.session?.user) throw new Error("Login required to save a Cash Run score.");
}

function normalizeLeaderboard(rows) {
    return (rows || []).map((row) => ({
        id: row.id,
        name: row.name,
        score: row.score,
        level: row.level,
        character: row.character,
        timestamp: row.timestamp,
    }));
}

export const submitScore = async ({ name, score, level, character, submissionId }) => {
    const client = await getSupabaseClient();
    if (client) {
        await requireSupabaseSession(client);
        const { data, error } = await client.rpc("submit_cash_run_score", {
            p_name: name,
            p_score: score,
            p_level: level,
            p_character: character,
            p_submission_id: submissionId,
        });
        if (error) throw error;
        return data;
    }

    const { data } = await axios.post(`${API}/leaderboard`, {
        name,
        score,
        level,
        character,
    });
    return data;
};

export const fetchLeaderboard = async (limit = 50) => {
    const client = await getSupabaseClient();
    if (client) {
        const { data, error } = await client.rpc("get_cash_run_leaderboard", { p_limit: limit });
        if (error) throw error;
        return normalizeLeaderboard(data);
    }

    const { data } = await axios.get(`${API}/leaderboard?limit=${limit}`);
    return data;
};

export const fetchRank = async (score) => {
    const client = await getSupabaseClient();
    if (client) {
        const { data, error } = await client.rpc("get_cash_run_rank", { p_score: score });
        if (error) throw error;
        return { rank: Number(data) || null };
    }

    const { data } = await axios.get(`${API}/leaderboard/rank?score=${score}`);
    return data;
};

export { CASH_RUN_GAME_KEY };
