import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import CharacterSelect from "../components/CharacterSelect";
import { audio } from "../game/audio";
import { Trophy, BookOpenText, Play, Volume2, VolumeX } from "lucide-react";

const storage = typeof window !== "undefined" ? window.localStorage : null;

export default function Menu() {
    const nav = useNavigate();
    const [character, setCharacter] = useState(() => storage?.getItem("cr-character") || "boy");
    const [mode, setMode] = useState(() => storage?.getItem("cr-mode") || "normal");
    const [muted, setMuted] = useState(audio.isMuted());
    const [soundStatus, setSoundStatus] = useState(audio.getStatus().state);

    useEffect(() => audio.subscribe(({ state }) => setSoundStatus(state)), []);
    useEffect(() => { storage?.setItem("cr-character", character); }, [character]);
    useEffect(() => { storage?.setItem("cr-mode", mode); }, [mode]);

    const startGame = () => {
        audio.unlock();
        if (!audio.isMuted()) audio.ready();
        nav("/play", { state: { character, mode } });
    };

    const toggleMute = async () => {
        const next = audio.toggleMuted();
        setMuted(next);
        if (!next) await audio.test();
    };

    const testSound = async () => {
        setMuted(false);
        setSoundStatus("testing");
        const result = await audio.test();
        setSoundStatus(result.played ? result.state : "blocked");
    };

    const soundStatusLabel = {
        muted: "Sound is off",
        waiting: "Tap Test Sound to connect audio",
        testing: "Testing sound…",
        "web-audio": "Sound ready",
        "media-fallback": "Sound ready (compatibility mode)",
        blocked: "Audio blocked — tap Test Sound again",
    }[soundStatus] || "Tap Test Sound";

    return (
        <div className="cr-page cr-bg-noir cr-grain" data-testid="menu-page">
            <div className="w-full max-w-3xl flex flex-col items-center pt-8 sm:pt-16">
                <div className="text-center cr-flicker">
                    <div className="cr-marquee mb-3" data-testid="menu-marquee">// CYBER ARCADE //</div>
                    <h1
                        className="font-arcade text-7xl sm:text-8xl"
                        style={{ color: "var(--cr-cash-bright)", textShadow: "0 0 24px rgba(126,232,149,0.55), 0 0 4px rgba(126,232,149,0.9), 0 0 60px rgba(108,242,255,0.25)" }}
                        data-testid="menu-title"
                    >
                        CASH_RUN
                    </h1>
                    <p className="font-arcade text-2xl mt-1" style={{ color: "var(--cr-gold)", textShadow: "0 0 12px rgba(255,216,74,0.5)" }} data-testid="menu-tagline">
                        chomp the cash. duck the heat.
                    </p>
                </div>

                <div className="w-full mt-6 mb-2 flex items-center justify-center gap-4 sm:gap-8 flex-wrap" data-testid="menu-hero" aria-hidden="true">
                    <img src="/games/cash-run/assets/tonio.webp" alt="" className="cr-hero" loading="eager" />
                    <img src="/games/cash-run/assets/nikki.webp" alt="" className="cr-hero cr-hero-alt" loading="eager" />
                </div>

                <div className="my-10">
                    <div className="font-arcade text-lg text-center mb-4" style={{ color: "var(--cr-ink-dim)" }}>— pick your hustler —</div>
                    <CharacterSelect value={character} onChange={setCharacter} />
                </div>

                <div className="mb-6 flex flex-col items-center gap-3" data-testid="mode-select">
                    <div className="font-arcade text-lg" style={{ color: "var(--cr-ink-dim)" }}>— difficulty —</div>
                    <div className="inline-flex p-1 rounded-full" style={{ background: "rgba(0,0,0,0.45)", border: "1px solid rgba(245,241,232,0.12)" }}>
                        {[
                            { id: "easy", label: "Practice", color: "var(--cr-cash-bright)" },
                            { id: "normal", label: "Normal", color: "var(--cr-gold)" },
                        ].map((m) => (
                            <button
                                key={m.id}
                                type="button"
                                onClick={() => setMode(m.id)}
                                data-testid={`mode-${m.id}`}
                                className="font-arcade text-xl px-5 py-1.5 rounded-full transition-all"
                                style={{ background: mode === m.id ? m.color : "transparent", color: mode === m.id ? "#0a0a0c" : m.color, letterSpacing: "0.04em" }}
                            >
                                {m.label}
                            </button>
                        ))}
                    </div>
                    <div className="font-mono text-xs" style={{ color: "var(--cr-ink-dim)" }} data-testid="mode-desc">
                        {mode === "easy" ? "Practice run — 5 lives, slower heat, cops appear later. Score won't be saved." : "Normal mode — score counts toward the global leaderboard."}
                    </div>
                </div>

                <div className="flex flex-wrap items-center justify-center gap-4 mb-8">
                    <button onClick={startGame} className="cr-btn cr-btn-primary" data-testid="menu-play-btn"><Play className="inline mr-2" size={18} />PLAY</button>
                    <button onClick={() => nav("/leaderboard")} className="cr-btn cr-btn-gold" data-testid="menu-leaderboard-btn"><Trophy className="inline mr-2" size={18} />LEADERBOARD</button>
                    <button onClick={() => nav("/how-to-play")} className="cr-btn" data-testid="menu-how-to-play-btn"><BookOpenText className="inline mr-2" size={18} />HOW TO PLAY</button>
                    <button onClick={toggleMute} className="cr-btn" style={{ padding: "0.85rem 1.1rem" }} data-testid="menu-mute-btn" aria-label={muted ? "Unmute" : "Mute"} title={muted ? "Unmute" : "Mute"}>
                        {muted ? <VolumeX className="inline mr-2" size={18} /> : <Volume2 className="inline mr-2" size={18} />}
                        {muted ? "SOUND OFF" : "SOUND ON"}
                    </button>
                    <button onClick={testSound} className="cr-btn" style={{ padding: "0.85rem 1.1rem", borderColor: "var(--cr-cash-bright)" }} data-testid="menu-test-sound-btn">
                        <Volume2 className="inline mr-2" size={18} />TEST SOUND
                    </button>
                </div>

                <div className="font-mono text-xs text-center mb-8" role="status" data-testid="menu-sound-status" style={{ color: soundStatus === "blocked" ? "#ff6b6b" : "var(--cr-cash-bright)" }}>
                    {soundStatusLabel}
                </div>

                <div className="cr-card max-w-xl text-center cr-float">
                    <div className="font-arcade text-xl mb-3" style={{ color: "var(--cr-gold)" }}>chase the bag with tonio &amp; nikki</div>
                    <p className="font-mono text-sm" style={{ color: "var(--cr-ink-dim)" }}>
                        Boot up in the Neo-Slum. Stack credits. Each level pushes you uptown — from rusted alleys to the Aurum Spire. Red thugs chase you straight, blue cops cut you off. Grab the BIG cash to flip the hunt.
                    </p>
                </div>

                <div className="mt-10 font-arcade text-sm cr-blink" style={{ color: "var(--cr-ink-dim)" }}>[ insert credit to continue ]</div>
            </div>
        </div>
    );
}
