export function getLevelForPoints(points = 0) {
    return [...COOL_POINTS_LEVELS].reverse().find((level) => points >= level.minPoints) || COOL_POINTS_LEVELS[0];
}

export function getNextLevelForPoints(points = 0) {
    return COOL_POINTS_LEVELS.find((level) => level.minPoints > points) || null;
}

export function getProgressForPoints(points = 0) {
    const currentLevel = getLevelForPoints(points);
    const nextLevel = getNextLevelForPoints(points);

    if (!nextLevel) {
        return {
            currentLevel,
            nextLevel: null,
            pointsIntoLevel: points - currentLevel.minPoints,
            pointsNeeded: 0,
            percent: 100,
        };
    }

    const span = nextLevel.minPoints - currentLevel.minPoints;
    const pointsIntoLevel = Math.max(0, points - currentLevel.minPoints);
    const percent = Math.min(100, Math.round((pointsIntoLevel / span) * 100));

    return {
        currentLevel,
        nextLevel,
        pointsIntoLevel,
        pointsNeeded: nextLevel.minPoints - points,
        percent,
    };
}
