import React from "react";
import { Sparkles } from "lucide-react";
import { useCoolPoints } from "../coolpoints/useCoolPoints";

export default function CoolPointsWidget({ compact = false }) {
    const { balance, currentLevel, progress, nextLevel } = useCoolPoints();

    return (
        <div className={`cp-widget ${compact ? "cp-widget-compact" : ""}`} data-testid="cool-points-widget">
            <div className="cp-widget-topline">
                <span className="cp-widget-icon"><Sparkles size={18} /></span>
                <span className="cp-widget-label">COOL POINTS</span>
            </div>
            <div className="cp-widget-balance">{balance.toLocaleString()} CP</div>
            <div className="cp-widget-rank">
                LVL {currentLevel.level} · {currentLevel.title}
            </div>
            {!compact && (
                <>
                    <div className="cp-progress-track" aria-label="Cool Points progress">
                        <div className="cp-progress-fill" style={{ width: `${progress.percent}%` }} />
                    </div>
                    <div className="cp-widget-next">
                        {nextLevel
                            ? `${progress.pointsNeeded.toLocaleString()} CP to ${nextLevel.title}`
                            : "MAX LEVEL · WORLD BOSS STATUS"}
                    </div>
                </>
            )}
        </div>
    );
}
