import React from "react";
import { useNavigate } from "react-router-dom";
import { ArrowLeft, Sparkles, Trophy } from "lucide-react";
import CoolPointsWidget from "../components/CoolPointsWidget";
import { useCoolPoints } from "../coolpoints/useCoolPoints";

const PLAY_COST = 100;
const BONUS_REWARD = 175;

export default function PlayLounge() {
    const nav = useNavigate();
    const {
        balance,
        spendCoolPoints,
        earnCoolPoints,
    } = useCoolPoints();

    const runPlayRound = () => {
        const approved = spendCoolPoints({
            amount: PLAY_COST,
            source: "casino",
            reason: "Play Lounge round entry",
        });

        if (!approved) {
            return;
        }

        const hitReward = Math.random() > 0.45;

        if (hitReward) {
            earnCoolPoints({
                amount: BONUS_REWARD,
                source: "casino",
                reason: "Play Lounge reward hit",
            });
        }
    };

    return (
        <div className="cr-page cr-bg-noir cr-grain" data-testid="play-lounge-page">
            <div className="w-full max-w-5xl flex flex-col items-center pt-8 sm:pt-14 px-4">
                <div className="w-full flex flex-col sm:flex-row justify-between items-center gap-4 mb-8">
                    <button onClick={() => nav("/lobby")} className="cr-btn" data-testid="play-lounge-back-btn">
                        <ArrowLeft className="inline mr-2" size={18} />
                        BACK TO LOBBY
                    </button>
                    <CoolPointsWidget compact />
                </div>

                <div className="text-center cr-flicker mb-10">
                    <div className="cr-marquee mb-3">HYPHSWORLD REWARD ARCADE</div>
                    <h1 className="font-arcade text-6xl sm:text-8xl cp-neon-title-alt">
                        PLAY LOUNGE
                    </h1>
                    <p className="font-arcade text-2xl mt-2" style={{ color: "var(--cr-double)" }}>
                        cool chips powered by cool points.
                    </p>
                </div>

                <div className="cp-play-card">
                    <div className="cp-play-chip-balance">
                        {balance.toLocaleString()} COOL CHIPS
                    </div>

                    <div className="cp-play-meta">
                        <div>
                            ROUND ENTRY
                            <strong>{PLAY_COST} CP</strong>
                        </div>
                        <div>
                            REWARD HIT
                            <strong>{BONUS_REWARD} CP</strong>
                        </div>
                    </div>

                    <button onClick={runPlayRound} className="cr-btn cr-btn-primary cp-play-btn" data-testid="play-lounge-round-btn">
                        <Sparkles className="inline mr-2" size={18} />
                        RUN PLAY ROUND
                    </button>
                </div>

                <div className="cp-play-notice cr-card text-center mt-10">
                    <div className="font-arcade text-2xl mb-4" style={{ color: "var(--cr-speed)" }}>
                        STACK COOL CHIPS
                    </div>

                    <p className="font-mono text-sm" style={{ color: "var(--cr-ink-dim)" }}>
                        Every round connects directly to your HyphsWorld Passport wallet.
                        Earn Cool Chips, unlock rewards, access new rooms, and build your status.
                    </p>

                    <div className="mt-6">
                        <button onClick={() => nav("/leaderboard")} className="cr-btn cr-btn-gold">
                            <Trophy className="inline mr-2" size={18} />
                            VIEW LEADERBOARD
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
}
