// Cash Run audio — Web Audio with an HTMLMediaElement fallback for iOS and in-app browsers.
// All sounds are generated locally; gameplay never depends on a remote audio file.

class CashRunAudio {
    constructor() {
        try {
            this.muted = window.localStorage.getItem("cr-muted") === "1";
        } catch {
            this.muted = false;
        }
        this._ctx = null;
        this._musicMaster = null;
        this._musicTimer = null;
        this._musicLevel = -1;
        this._lastMusicLevel = 1;
        this._wantedMusicLevel = null;
        this._fallbackMusic = null;
        this._fallbackCache = new Map();
        this._chompFlip = false;
        this._unlockPromise = null;
        this._status = this.muted ? "muted" : "waiting";
        this._lastError = "";
        this._listeners = new Set();
        this._installUnlockListeners();
    }

    setMuted(value) {
        this.muted = Boolean(value);
        try {
            window.localStorage.setItem("cr-muted", this.muted ? "1" : "0");
        } catch (error) {
            console.warn("Failed to persist Cash Run sound preference", error);
        }
        if (this.muted) {
            this.stopMusic();
            this._setStatus("muted");
        } else {
            this._setStatus("waiting");
            this.unlock().then(() => this._resumeDesiredMusic());
        }
    }

    isMuted() { return this.muted; }
    toggleMuted() { this.setMuted(!this.muted); return this.muted; }
    getStatus() { return { state: this._status, error: this._lastError, muted: this.muted }; }

    subscribe(listener) {
        this._listeners.add(listener);
        listener(this.getStatus());
        return () => this._listeners.delete(listener);
    }

    _setStatus(state, error = "") {
        this._status = state;
        this._lastError = error ? String(error?.message || error) : "";
        const detail = this.getStatus();
        this._listeners.forEach((listener) => {
            try { listener(detail); } catch (listenerError) { console.warn("Cash Run sound listener failed", listenerError); }
        });
    }

    _ensureCtx() {
        if (typeof window === "undefined") return null;
        if (this._ctx?.state === "closed") {
            this._ctx = null;
            this._musicMaster = null;
            this._musicTimer = null;
        }
        if (!this._ctx) {
            const AudioContextClass = window.AudioContext || window.webkitAudioContext;
            if (AudioContextClass) {
                try {
                    this._ctx = new AudioContextClass();
                    this._ctx.addEventListener?.("statechange", () => {
                        if (this.muted) return;
                        if (this._ctx?.state === "running") {
                            this._setStatus("web-audio");
                            this._resumeDesiredMusic();
                        }
                    });
                } catch (error) {
                    this._setStatus("media-fallback", error);
                }
            }
        }
        return this._ctx;
    }

    _installUnlockListeners() {
        if (typeof window === "undefined" || typeof document === "undefined") return;
        const resume = () => {
            if (!this.muted) this.unlock().then(() => this._resumeDesiredMusic());
        };
        window.addEventListener("pointerdown", resume, { passive: true, capture: true });
        window.addEventListener("touchend", resume, { passive: true, capture: true });
        window.addEventListener("keydown", resume, { capture: true });
        window.addEventListener("pageshow", resume, { passive: true });
        document.addEventListener("visibilitychange", () => {
            if (!document.hidden) resume();
        });
    }

    async unlock() {
        if (this.muted) return false;
        const ctx = this._ensureCtx();
        if (!ctx) {
            this._setStatus("media-fallback");
            return false;
        }
        if (ctx.state === "running") {
            this._setStatus("web-audio");
            return true;
        }
        if (this._unlockPromise) return this._unlockPromise;

        this._unlockPromise = Promise.resolve(typeof ctx.resume === "function" ? ctx.resume() : undefined)
            .then(() => {
                if (ctx.state !== "running") return false;
                const source = ctx.createBufferSource();
                source.buffer = ctx.createBuffer(1, 1, 22050);
                source.connect(ctx.destination);
                source.start(0);
                this._setStatus("web-audio");
                return true;
            })
            .catch((error) => {
                console.warn("Cash Run Web Audio could not unlock; using media fallback", error);
                this._setStatus("media-fallback", error);
                return false;
            })
            .finally(() => { this._unlockPromise = null; });
        return this._unlockPromise;
    }

    _wavUrl(notes, key) {
        if (this._fallbackCache.has(key)) return this._fallbackCache.get(key);
        const sampleRate = 11025;
        const gap = 0.012;
        const totalSeconds = notes.reduce((sum, note) => sum + note.dur + gap, 0);
        const sampleCount = Math.max(1, Math.ceil(totalSeconds * sampleRate));
        const bytes = new Uint8Array(44 + sampleCount * 2);
        const view = new DataView(bytes.buffer);
        const write = (offset, value) => [...value].forEach((char, index) => view.setUint8(offset + index, char.charCodeAt(0)));
        write(0, "RIFF");
        view.setUint32(4, 36 + sampleCount * 2, true);
        write(8, "WAVEfmt ");
        view.setUint32(16, 16, true);
        view.setUint16(20, 1, true);
        view.setUint16(22, 1, true);
        view.setUint32(24, sampleRate, true);
        view.setUint32(28, sampleRate * 2, true);
        view.setUint16(32, 2, true);
        view.setUint16(34, 16, true);
        write(36, "data");
        view.setUint32(40, sampleCount * 2, true);

        let cursor = 0;
        for (const note of notes) {
            const noteSamples = Math.floor(note.dur * sampleRate);
            for (let i = 0; i < noteSamples && cursor < sampleCount; i += 1, cursor += 1) {
                const time = i / sampleRate;
                const progress = i / Math.max(1, noteSamples - 1);
                const frequency = note.freqEnd == null ? note.freq : note.freq + (note.freqEnd - note.freq) * progress;
                const phase = 2 * Math.PI * frequency * time;
                let wave;
                if (note.type === "square") wave = Math.sin(phase) >= 0 ? 1 : -1;
                else if (note.type === "sawtooth") wave = 2 * ((time * frequency) % 1) - 1;
                else if (note.type === "triangle") wave = 2 * Math.asin(Math.sin(phase)) / Math.PI;
                else wave = Math.sin(phase);
                const envelope = Math.min(1, i / 45) * Math.pow(1 - progress, 1.35);
                view.setInt16(44 + cursor * 2, Math.max(-32767, Math.min(32767, wave * envelope * 24500)), true);
            }
            cursor += Math.floor(gap * sampleRate);
        }

        let binary = "";
        const chunk = 0x8000;
        for (let offset = 0; offset < bytes.length; offset += chunk) {
            binary += String.fromCharCode(...bytes.subarray(offset, offset + chunk));
        }
        const url = `data:audio/wav;base64,${window.btoa(binary)}`;
        this._fallbackCache.set(key, url);
        return url;
    }

    async _playMedia(notes, volume = 0.28, key = "tone", loop = false) {
        if (this.muted || typeof window === "undefined" || typeof window.Audio !== "function") return false;
        try {
            const media = new window.Audio(this._wavUrl(notes, key));
            media.preload = "auto";
            media.loop = loop;
            media.volume = Math.max(0, Math.min(1, volume));
            media.setAttribute("playsinline", "");
            media.setAttribute("webkit-playsinline", "");
            await media.play();
            this._setStatus("media-fallback");
            return media;
        } catch (error) {
            console.warn("Cash Run media audio could not play", error);
            this._setStatus("blocked", error);
            return false;
        }
    }

    _webTone(note, master = null) {
        const ctx = this._ctx;
        if (!ctx || ctx.state !== "running") return false;
        const start = ctx.currentTime;
        const oscillator = ctx.createOscillator();
        oscillator.type = note.type || "square";
        oscillator.frequency.setValueAtTime(note.freq, start);
        if (note.freqEnd != null) oscillator.frequency.linearRampToValueAtTime(note.freqEnd, start + note.dur);
        const gain = ctx.createGain();
        gain.gain.setValueAtTime(0.0001, start);
        gain.gain.linearRampToValueAtTime(note.vol ?? 0.12, start + 0.006);
        gain.gain.exponentialRampToValueAtTime(0.001, start + note.dur);
        oscillator.connect(gain);
        gain.connect(master || ctx.destination);
        oscillator.start(start);
        oscillator.stop(start + note.dur + 0.025);
        return true;
    }

    async _tone(note) {
        if (this.muted) return false;
        const unlocked = await this.unlock();
        if (unlocked && this._webTone(note)) return true;
        return Boolean(await this._playMedia([note], Math.max(0.24, (note.vol || 0.12) * 2.2), `tone-${note.freq}-${note.freqEnd || 0}-${note.type || "square"}-${note.dur}`));
    }

    async _seq(notes, baseVol = 0.12) {
        if (this.muted) return false;
        const normalized = notes.map((note) => ({ ...note, vol: note.vol ?? baseVol }));
        const unlocked = await this.unlock();
        if (unlocked && this._ctx?.state === "running") {
            let offset = 0;
            for (const note of normalized) {
                const ctx = this._ctx;
                const start = ctx.currentTime + offset;
                const oscillator = ctx.createOscillator();
                oscillator.type = note.type || "square";
                oscillator.frequency.setValueAtTime(note.freq, start);
                const gain = ctx.createGain();
                gain.gain.setValueAtTime(0.0001, start);
                gain.gain.linearRampToValueAtTime(note.vol, start + 0.006);
                gain.gain.exponentialRampToValueAtTime(0.001, start + note.dur);
                oscillator.connect(gain);
                gain.connect(ctx.destination);
                oscillator.start(start);
                oscillator.stop(start + note.dur + 0.025);
                offset += note.dur * 0.9;
            }
            return true;
        }
        const key = `seq-${normalized.map((note) => `${note.freq}-${note.dur}-${note.type || "square"}`).join("_")}`;
        return Boolean(await this._playMedia(normalized, Math.max(0.3, baseVol * 2.4), key));
    }

    collect() {
        this._chompFlip = !this._chompFlip;
        return this._tone({ freq: this._chompFlip ? 880 : 660, type: "square", dur: 0.055, vol: 0.1 });
    }
    bigCash() { return this._seq([{ freq: 440, dur: 0.08 }, { freq: 660, dur: 0.08 }, { freq: 880, dur: 0.13, type: "triangle" }], 0.16); }
    eatEnemy() { return this._seq([{ freq: 220, dur: 0.06, type: "sawtooth" }, { freq: 330, dur: 0.06, type: "sawtooth" }, { freq: 494, dur: 0.07, type: "sawtooth" }, { freq: 660, dur: 0.09, type: "sawtooth" }, { freq: 880, dur: 0.13, type: "triangle" }], 0.17); }
    powerUp() { return this._tone({ freq: 440, freqEnd: 1320, type: "triangle", dur: 0.2, vol: 0.18 }); }
    shieldHit() { return this._tone({ freq: 1400, freqEnd: 220, type: "square", dur: 0.2, vol: 0.2 }); }
    death() { return this._seq([{ freq: 660, dur: 0.11, type: "sawtooth" }, { freq: 523, dur: 0.11, type: "sawtooth" }, { freq: 392, dur: 0.13, type: "sawtooth" }, { freq: 294, dur: 0.17, type: "sawtooth" }, { freq: 196, dur: 0.22, type: "sawtooth" }, { freq: 110, dur: 0.32, type: "sawtooth" }], 0.2); }
    levelUp() { return this._seq([{ freq: 523, dur: 0.1 }, { freq: 659, dur: 0.1 }, { freq: 784, dur: 0.1 }, { freq: 1047, dur: 0.22, type: "triangle" }], 0.2); }
    ready() { return this._seq([{ freq: 660, dur: 0.1, type: "triangle" }, { freq: 880, dur: 0.16, type: "triangle" }], 0.19); }
    test() {
        this.setMuted(false);
        return this.ready().then((played) => ({ played: Boolean(played), ...this.getStatus() }));
    }

    startMusic(level) {
        this._lastMusicLevel = Number(level) || 1;
        this._wantedMusicLevel = this._lastMusicLevel;
        if (this.muted) return;
        this.unlock().then((unlocked) => {
            if (this.muted || this._wantedMusicLevel == null) return;
            if (unlocked && this._ctx?.state === "running") this._startWebMusic(this._wantedMusicLevel);
            else this._startFallbackMusic(this._wantedMusicLevel);
        });
    }

    _theme(level) {
        const themes = [
            { root: 110, scale: [0, 3, 5, 7, 10], tempo: 96, type: "triangle", bass: "sine" },
            { root: 130, scale: [0, 3, 5, 7, 10], tempo: 110, type: "sawtooth", bass: "triangle" },
            { root: 147, scale: [0, 2, 4, 7, 9], tempo: 120, type: "triangle", bass: "sine" },
            { root: 165, scale: [0, 2, 4, 7, 9], tempo: 132, type: "square", bass: "triangle" },
            { root: 196, scale: [0, 2, 4, 7, 9], tempo: 124, type: "sine", bass: "triangle" },
        ];
        return themes[((level - 1) % themes.length + themes.length) % themes.length];
    }

    _startWebMusic(level) {
        if (this._musicLevel === level && this._musicTimer && this._musicMaster) return;
        this._stopActiveMusic(false);
        const ctx = this._ctx;
        if (!ctx || ctx.state !== "running") return this._startFallbackMusic(level);
        const theme = this._theme(level);
        const beatLength = 60 / theme.tempo / 2;
        const master = ctx.createGain();
        master.gain.value = 0.19;
        master.connect(ctx.destination);
        this._musicMaster = master;
        this._musicLevel = level;
        let beat = 0;
        const arpeggio = [0, 2, 4, 2, 1, 3, 4, 3];
        const bassPattern = [0, 0, 4, 0, 3, 3, 4, 4];
        const tick = () => {
            if (this.muted || !this._musicMaster || ctx.state !== "running") return;
            const leadIndex = arpeggio[beat % arpeggio.length];
            const leadSemi = theme.scale[leadIndex % theme.scale.length];
            const leadFreq = theme.root * Math.pow(2, leadSemi / 12 + Math.floor(leadIndex / theme.scale.length));
            this._scheduleMusicTone(leadFreq, theme.type, beatLength * 0.9, 0.38, master, 0.035);
            if (beat % 2 === 0) {
                const bassSemi = theme.scale[bassPattern[(beat / 2) % bassPattern.length] % theme.scale.length];
                this._scheduleMusicTone((theme.root / 2) * Math.pow(2, bassSemi / 12), theme.bass, beatLength * 1.8, 0.55, master, 0.035);
            }
            beat += 1;
        };
        tick();
        this._musicTimer = window.setInterval(tick, beatLength * 1000);
        this._setStatus("web-audio");
    }

    _scheduleMusicTone(freq, type, dur, volume, master, delay) {
        const ctx = this._ctx;
        const start = ctx.currentTime + delay;
        const oscillator = ctx.createOscillator();
        oscillator.type = type;
        oscillator.frequency.value = freq;
        const gain = ctx.createGain();
        gain.gain.setValueAtTime(0.0001, start);
        gain.gain.linearRampToValueAtTime(volume, start + 0.008);
        gain.gain.exponentialRampToValueAtTime(0.001, start + dur);
        oscillator.connect(gain);
        gain.connect(master);
        oscillator.start(start);
        oscillator.stop(start + dur + 0.02);
    }

    async _startFallbackMusic(level) {
        if (this.muted || this._wantedMusicLevel == null) return;
        if (this._fallbackMusic && this._musicLevel === level && !this._fallbackMusic.paused) return;
        this._stopActiveMusic(false);
        const theme = this._theme(level);
        const pattern = [0, 2, 4, 2, 1, 3, 4, 3, 0, 1, 3, 1, 4, 3, 2, 1];
        const noteDuration = 60 / theme.tempo / 2;
        const notes = pattern.map((index) => ({
            freq: theme.root * 2 * Math.pow(2, theme.scale[index % theme.scale.length] / 12),
            dur: noteDuration * 0.82,
            type: theme.type,
        }));
        const media = await this._playMedia(notes, 0.42, `music-${level}-${theme.tempo}`, true);
        if (media) {
            this._fallbackMusic = media;
            this._musicLevel = level;
        }
    }

    _resumeDesiredMusic() {
        if (!this.muted && this._wantedMusicLevel != null) this.startMusic(this._wantedMusicLevel);
    }

    _stopActiveMusic(fade = true) {
        if (this._musicTimer) {
            window.clearInterval(this._musicTimer);
            this._musicTimer = null;
        }
        if (this._fallbackMusic) {
            try { this._fallbackMusic.pause(); this._fallbackMusic.currentTime = 0; } catch (error) { console.warn("Failed to stop fallback music", error); }
            this._fallbackMusic = null;
        }
        if (this._musicMaster && this._ctx) {
            const master = this._musicMaster;
            try {
                const now = this._ctx.currentTime;
                master.gain.cancelScheduledValues(now);
                master.gain.setValueAtTime(master.gain.value, now);
                master.gain.linearRampToValueAtTime(0.0001, now + (fade ? 0.18 : 0.01));
                window.setTimeout(() => { try { master.disconnect(); } catch {} }, fade ? 240 : 30);
            } catch (error) {
                console.warn("Failed to stop Web Audio music", error);
            }
            this._musicMaster = null;
        }
        this._musicLevel = -1;
    }

    stopMusic() {
        this._wantedMusicLevel = null;
        this._stopActiveMusic(true);
    }
}

export const audio = new CashRunAudio();
