import React from "react";

const CHARACTERS = [
    { id: "boy", label: "TONIO", sub: "Chase the bag", color: "#e0413a", image: "/games/cash-run/assets/tonio.webp" },
    { id: "girl", label: "NIKKI", sub: "Fast hands", color: "#ff3ec8", image: "/games/cash-run/assets/nikki.webp" },
];

export default function CharacterSelect({ value, onChange }) {
    return (
        <div className="flex items-center gap-6 justify-center" data-testid="character-select">
            {CHARACTERS.map((character) => (
                <button
                    key={character.id}
                    type="button"
                    onClick={() => onChange(character.id)}
                    className={`cr-char-card ${value === character.id ? "selected" : ""}`}
                    data-testid={`character-option-${character.id}`}
                >
                    <img
                        src={character.image}
                        alt={character.label}
                        style={{ width: 110, height: 110, objectFit: "contain" }}
                        loading="eager"
                    />
                    <div className="text-center">
                        <div className="font-arcade text-2xl" style={{ color: character.color }}>{character.label}</div>
                        <div className="font-mono text-xs" style={{ color: "var(--cr-ink-dim)" }}>{character.sub}</div>
                    </div>
                </button>
            ))}
        </div>
    );
}

export function CharacterAvatar({ variant = "boy", size = 60 }) {
    const character = CHARACTERS.find((item) => item.id === variant) || CHARACTERS[0];
    return <img src={character.image} alt={character.label} width={size} height={size} style={{ objectFit: "contain" }} />;
}
