// Cash Run game engine — tile-based, canvas rendered.
import {
    buildGrid,
    isWall,
    wrap,
    countPellets,
    PLAYER_SPAWN,
    ENEMY_SPAWNS,
    POWERUP_SPOTS,
    COLS,
    ROWS,
    T,
} from "./maze";
import { getTheme, getDifficulty, POWERUP_TYPES } from "./themes";
import { audio } from "./audio";


const PLAYER_SPRITES = {
    boy: "/games/cash-run/assets/tonio.webp",
    girl: "/games/cash-run/assets/nikki.webp",
};
const spriteCache = {};
const spriteLoading = {};

function trimTransparentSprite(image) {
    const source = document.createElement("canvas");
    const width = image.naturalWidth;
    const height = image.naturalHeight;
    const ctx = source.getContext("2d", { willReadFrequently: true });
    source.width = width;
    source.height = height;
    ctx.drawImage(image, 0, 0);
    const pixels = ctx.getImageData(0, 0, width, height).data;
    let left = width, top = height, right = -1, bottom = -1;
    for (let y = 0; y < height; y += 1) {
        for (let x = 0; x < width; x += 1) {
            if (pixels[(y * width + x) * 4 + 3] > 8) {
                left = Math.min(left, x);
                top = Math.min(top, y);
                right = Math.max(right, x);
                bottom = Math.max(bottom, y);
            }
        }
    }
    if (right < left || bottom < top) return image;
    const trimmed = document.createElement("canvas");
    trimmed.width = right - left + 1;
    trimmed.height = bottom - top + 1;
    trimmed.getContext("2d").drawImage(image, left, top, trimmed.width, trimmed.height, 0, 0, trimmed.width, trimmed.height);
    return trimmed;
}

function getPlayerSprite(character) {
    if (spriteCache[character]) return spriteCache[character];
    if (spriteLoading[character]) return null;
    const image = new Image();
    image.crossOrigin = "anonymous";
    spriteLoading[character] = new Promise((resolve) => {
        image.onload = () => {
            try {
                spriteCache[character] = trimTransparentSprite(image);
            } catch (error) {
                console.warn(`[cash-run] sprite key-out failed for ${character}:`, error);
                spriteCache[character] = image;
            }
            resolve(spriteCache[character]);
        };
        image.onerror = (error) => {
            console.warn(`[cash-run] sprite load failed for ${character}:`, error);
            resolve(null);
        };
    });
    image.src = PLAYER_SPRITES[character];
    return null;
}

getPlayerSprite("boy");
getPlayerSprite("girl");

const DIRS = {
    up:    { dc:  0, dr: -1 },
    down:  { dc:  0, dr:  1 },
    left:  { dc: -1, dr:  0 },
    right: { dc:  1, dr:  0 },
};
const OPP = { up: "down", down: "up", left: "right", right: "left" };

const TILE = 26;     // px per tile
const PAD  = 0;
export const CANVAS_W = COLS * TILE + PAD * 2;
export const CANVAS_H = ROWS * TILE + PAD * 2;

const EPS = 0.06;
const POWERUP_WEIGHTS = {
    speed: 3,
    shield: 3,
    double: 3,
    bomb: 1,
    life: 1,
};

function manhattan(a, b) { return Math.abs(a.col - b.col) + Math.abs(a.row - b.row); }
function dist2(a, b) {
    const dx = a.col - b.col, dy = a.row - b.row;
    return dx * dx + dy * dy;
}

export class CashRunEngine {
    constructor(canvas, opts = {}) {
        this.canvas = canvas;
        this.ctx = canvas.getContext("2d");
        canvas.width = CANVAS_W;
        canvas.height = CANVAS_H;

        this.character = opts.character || "boy";
        this.mode = opts.mode === "easy" ? "easy" : "normal";
        this.onLifeLost = opts.onLifeLost || (() => {});
        this.onLivesChange = opts.onLivesChange || null;
        this.onGameOver = opts.onGameOver || (() => {});
        this.onLevelComplete = opts.onLevelComplete || (() => {});
        this.onScoreChange = opts.onScoreChange || (() => {});
        this.onStateChange = opts.onStateChange || (() => {});

        this.score = 0;
        this.lives = this.mode === "easy" ? 5 : 3;
        this.level = 1;
        this.cashCollected = 0;

        this.running = false;
        this.paused = false;
        this._raf = null;
        this._lastTs = 0;
        this._readyTimer = 2.0;     // intro delay before move
        this.activePower = null;     // { type, time }
        this.frightened = 0;          // seconds remaining of fright
        this.frightChain = 0;         // for 200/400/800 ghost combo
        this._powerUpsActive = [];    // [{type,col,row}]
        this._powerUpTimer = 5;       // seconds until next spawn
        this._floatTexts = [];        // floating score popups
        this._screenShake = 0;        // seconds remaining
        this._lastBombWipe = 0;
        this._debugHud = false;

        this._initLevel();
        this._bindKeys();
    }

    _initLevel() {
        const theme = getTheme(this.level);
        const diff = getDifficulty(this.level, this.mode);
        this.theme = theme;
        this.diff = diff;

        this.grid = buildGrid();
        this.totalPellets = countPellets(this.grid);
        this.eatenPellets = 0;

        this.player = {
            col: PLAYER_SPAWN.col + 0.0,
            row: PLAYER_SPAWN.row + 0.0,
            dir: "left",
            queued: null,
            speed: diff.playerSpeed,
        };

        this.enemies = [];
        for (let i = 0; i < diff.enemyCount; i++) {
            const spawn = ENEMY_SPAWNS[i % ENEMY_SPAWNS.length];
            // In Easy mode: only thugs until level 3. Otherwise mix from level 2.
            let type = "thug";
            const copsAllowed = this.mode === "easy" ? this.level >= 3 : this.level >= 2;
            if (copsAllowed && i % 2 === 1) type = "cop";
            this.enemies.push({
                col: spawn.col + 0.0,
                row: spawn.row + 0.0,
                dir: ["up", "left", "right"][i % 3],
                speed: diff.enemySpeed,
                type,
                state: "exit",
                home: { col: spawn.col, row: spawn.row },
                releaseAt: i * (this.mode === "easy" ? 1.8 : 1.2),
                exited: false,
            });
        }

        this._powerUpsActive = [];
        this._powerUpTimer = 4 + Math.random() * 3;
        this._readyTimer = 2.0;
        this.frightened = 0;
        this.frightChain = 0;
        this.activePower = null;
        this._floatTexts = [];

        this.onStateChange?.({
            level: this.level, score: this.score, lives: this.lives, theme,
            ready: true, activePower: null, cashCollected: this.cashCollected,
        });
    }

    start() {
        if (this.running) return;
        this.running = true;
        this._lastTs = performance.now();
        audio.unlock();
        audio.startMusic(this.level);
        const tick = (ts) => {
            if (!this.running) return;
            const dt = Math.min((ts - this._lastTs) / 1000, 0.05);
            this._lastTs = ts;
            if (!this.paused) this._update(dt);
            this._render();
            this._raf = requestAnimationFrame(tick);
        };
        this._raf = requestAnimationFrame(tick);
    }

    stop() {
        this.running = false;
        if (this._raf) cancelAnimationFrame(this._raf);
        document.removeEventListener("keydown", this._keyHandler);
        audio.stopMusic();
    }

    pause(p) { this.paused = !!p; }
    togglePause() { this.paused = !this.paused; }

    setDirection(dir) {
        if (!DIRS[dir]) return;
        this.player.queued = dir;
    }

    _bindKeys() {
        this._keyHandler = (e) => {
            const k = e.key.toLowerCase();
            if (k === "arrowup" || k === "w") { this.setDirection("up"); e.preventDefault(); }
            else if (k === "arrowdown" || k === "s") { this.setDirection("down"); e.preventDefault(); }
            else if (k === "arrowleft" || k === "a") { this.setDirection("left"); e.preventDefault(); }
            else if (k === "arrowright" || k === "d") { this.setDirection("right"); e.preventDefault(); }
            else if (k === "p" || k === "escape") { this.togglePause(); }
            else if (k === "`") { this._debugHud = !this._debugHud; }
        };
        document.addEventListener("keydown", this._keyHandler);
    }

    // ---------- Update ----------
    _update(dt) {
        if (this._readyTimer > 0) {
            this._readyTimer -= dt;
            return;
        }

        // Power timers
        if (this.activePower) {
            this.activePower.time -= dt;
            if (this.activePower.time <= 0) this.activePower = null;
        }
        if (this.frightened > 0) {
            this.frightened -= dt;
            if (this.frightened <= 0) this.frightChain = 0;
        }

        // Power-up spawning
        this._powerUpTimer -= dt;
        if (this._powerUpTimer <= 0 && this._powerUpsActive.length < 2) {
            const free = POWERUP_SPOTS.filter(s =>
                !isWall(this.grid, s.col, s.row) &&
                !this._powerUpsActive.some(p => p.col === s.col && p.row === s.row)
            );
            if (free.length) {
                const spot = free[Math.floor(Math.random() * free.length)];
                const type = this._pickPowerUpType();
                this._powerUpsActive.push({ ...spot, type, life: 8 });
            }
            this._powerUpTimer = 6 + Math.random() * 4;
        }
        // Decay power-ups on board
        this._powerUpsActive = this._powerUpsActive.filter(p => {
            p.life -= dt;
            return p.life > 0;
        });

        this._movePlayer(dt);
        this._collectPellet();
        this._collectPowerUp();
        this._moveEnemies(dt);
        this._checkCollisions();

        // Update floating texts
        this._floatTexts = this._floatTexts.filter(f => {
            f.life -= dt;
            f.row -= dt * 0.8;
            return f.life > 0;
        });
        if (this._screenShake > 0) this._screenShake = Math.max(0, this._screenShake - dt);

        // Level complete?
        if (this.eatenPellets >= this.totalPellets) {
            this._nextLevel();
        }
    }

    _movePlayer(dt) {
        const p = this.player;
        const speedMul = this.activePower?.type === "speed" ? 1.45 : 1.0;
        const step = p.speed * speedMul * dt;

        // Try queued direction at integer-aligned axis-perpendicular moments.
        if (p.queued && p.queued !== p.dir) {
            const at = DIRS[p.queued];
            // Check the perpendicular alignment to current direction
            const onTile = (x) => Math.abs(x - Math.round(x)) < EPS;
            if (at.dc !== 0) {
                if (onTile(p.row)) {
                    const tCol = Math.round(p.col);
                    const tRow = Math.round(p.row);
                    const ahead = wrap(tCol + at.dc, tRow);
                    if (!isWall(this.grid, ahead.col, ahead.row)) {
                        p.row = tRow;
                        p.dir = p.queued;
                        p.queued = null;
                    }
                }
            } else {
                if (onTile(p.col)) {
                    const tCol = Math.round(p.col);
                    const tRow = Math.round(p.row);
                    const ahead = wrap(tCol, tRow + at.dr);
                    if (!isWall(this.grid, ahead.col, ahead.row)) {
                        p.col = tCol;
                        p.dir = p.queued;
                        p.queued = null;
                    }
                }
            }
        }

        const d = DIRS[p.dir];
        // Predict next tile when crossing center
        const nextCol = p.col + d.dc * step;
        const nextRow = p.row + d.dr * step;

        // If facing wall and roughly at tile center, stop
        const tCol = Math.round(p.col);
        const tRow = Math.round(p.row);
        const aheadTile = wrap(tCol + d.dc, tRow + d.dr);
        const wallAhead = isWall(this.grid, aheadTile.col, aheadTile.row);

        if (wallAhead) {
            // distance from current to center along dir
            if (d.dc !== 0) {
                if ((d.dc > 0 && nextCol >= tCol) || (d.dc < 0 && nextCol <= tCol)) {
                    p.col = tCol;
                } else {
                    p.col = nextCol;
                }
            } else {
                if ((d.dr > 0 && nextRow >= tRow) || (d.dr < 0 && nextRow <= tRow)) {
                    p.row = tRow;
                } else {
                    p.row = nextRow;
                }
            }
        } else {
            p.col = nextCol;
            p.row = nextRow;
        }

        // Tunnel wrap
        if (p.col < -0.4) p.col = COLS - 0.5;
        else if (p.col > COLS - 0.6) p.col = -0.5;
    }

    _collectPellet() {
        const p = this.player;
        const tc = Math.round(p.col);
        const tr = Math.round(p.row);
        if (tc < 0 || tc >= COLS || tr < 0 || tr >= ROWS) return;
        // Must be near center
        if (Math.abs(p.col - tc) > 0.4 || Math.abs(p.row - tr) > 0.4) return;

        const v = this.grid[tr][tc];
        if (v === T.PELLET) {
            this.grid[tr][tc] = T.EMPTY;
            this.eatenPellets++;
            this.cashCollected += 10;
            const mult = this.activePower?.type === "double" ? 2 : 1;
            this._addScore(10 * mult);
            audio.collect();
        } else if (v === T.POWER) {
            this.grid[tr][tc] = T.EMPTY;
            this.eatenPellets++;
            this.cashCollected += 50;
            const mult = this.activePower?.type === "double" ? 2 : 1;
            this._addScore(50 * mult);
            this.frightened = this.diff.frightTime;
            this.frightChain = 0;
            // flip non-eyes enemies to frightened
            for (const e of this.enemies) {
                if (e.state !== "eyes") e.state = "fright";
            }
            audio.bigCash();
        }
    }

    _collectPowerUp() {
        const p = this.player;
        const tc = Math.round(p.col);
        const tr = Math.round(p.row);
        for (let i = 0; i < this._powerUpsActive.length; i++) {
            const pu = this._powerUpsActive[i];
            if (pu.col === tc && pu.row === tr &&
                Math.abs(p.col - tc) < 0.4 && Math.abs(p.row - tr) < 0.4) {
                this._powerUpsActive.splice(i, 1);
                if (pu.type === "bomb") {
                    let wiped = 0;
                    for (const e of this.enemies) {
                        if (e.state !== "eyes") {
                            e.state = "eyes";
                            wiped++;
                        }
                    }
                    const pts = 200 * Math.max(1, wiped);
                    this._lastBombWipe = wiped;
                    this._addScore(pts);
                    this._popText(`BOOM +${pts}`, tc, tr, "#ff6b3a");
                    this._screenShake = 0.6;
                    audio.eatEnemy();
                    return;
                }
                if (pu.type === "life") {
                    this.lives = Math.min(this.lives + 1, 9);
                    this.onLivesChange?.(this.lives);
                    this._addScore(50);
                    this._popText("+1 LIFE", tc, tr, "#ff5577");
                    audio.levelUp();
                    return;
                }

                this.activePower = { type: pu.type, time: 6 };
                this._addScore(25);
                this._popText("+25", tc, tr, "#ffd84a");
                audio.powerUp();
                return;
            }
        }
    }

    _moveEnemies(dt) {
        for (const e of this.enemies) {
            // Release timer
            if (!e.exited) {
                e.releaseAt -= dt;
                if (e.releaseAt > 0) {
                    // bobble in pen
                    continue;
                }
                e.exited = true;
                e.state = this.frightened > 0 ? "fright" : "chase";
            }

            const onTile =
                Math.abs(e.col - Math.round(e.col)) < EPS &&
                Math.abs(e.row - Math.round(e.row)) < EPS;

            if (onTile) {
                e.col = Math.round(e.col);
                e.row = Math.round(e.row);

                const tc = e.col, tr = e.row;
                // Determine target
                let target;
                if (e.state === "eyes") {
                    target = e.home;
                    if (tc === e.home.col && tr === e.home.row) {
                        e.state = this.frightened > 0 ? "fright" : "chase";
                    }
                } else if (e.state === "fright") {
                    target = null; // random
                } else {
                    if (e.type === "thug") {
                        target = { col: Math.round(this.player.col), row: Math.round(this.player.row) };
                    } else { // cop
                        const d = DIRS[this.player.dir];
                        target = {
                            col: Math.round(this.player.col) + d.dc * 4,
                            row: Math.round(this.player.row) + d.dr * 4,
                        };
                    }
                }

                // Available directions (no reverse, no walls)
                const opts = [];
                for (const dirName of ["up", "left", "down", "right"]) {
                    if (dirName === OPP[e.dir]) continue;
                    const d = DIRS[dirName];
                    const nx = wrap(tc + d.dc, tr + d.dr);
                    if (!isWall(this.grid, nx.col, nx.row)) opts.push(dirName);
                }
                if (opts.length === 0) {
                    // dead-end: allow reverse
                    e.dir = OPP[e.dir];
                } else if (target == null) {
                    e.dir = opts[Math.floor(Math.random() * opts.length)];
                } else {
                    let best = opts[0];
                    let bestD = Infinity;
                    for (const dirName of opts) {
                        const d = DIRS[dirName];
                        const nx = wrap(tc + d.dc, tr + d.dr);
                        const dd = dist2(nx, target);
                        if (dd < bestD) { bestD = dd; best = dirName; }
                    }
                    e.dir = best;
                }
            }

            const speed = e.state === "fright" ? e.speed * 0.55
                        : e.state === "eyes"   ? e.speed * 1.6
                        :                        e.speed;
            const d = DIRS[e.dir];
            const nc = e.col + d.dc * speed * dt;
            const nr = e.row + d.dr * speed * dt;
            const aheadTile = wrap(Math.round(e.col) + d.dc, Math.round(e.row) + d.dr);
            if (isWall(this.grid, aheadTile.col, aheadTile.row)) {
                e.col = Math.round(e.col);
                e.row = Math.round(e.row);
            } else {
                e.col = nc;
                e.row = nr;
            }
            // Tunnel wrap
            if (e.col < -0.4) e.col = COLS - 0.5;
            else if (e.col > COLS - 0.6) e.col = -0.5;
        }
    }

    _checkCollisions() {
        const p = this.player;
        for (const e of this.enemies) {
            if (e.state === "eyes") continue;
            const dx = p.col - e.col;
            const dy = p.row - e.row;
            if (dx * dx + dy * dy < 0.55 * 0.55) {
                if (e.state === "fright") {
                    // Eat enemy
                    e.state = "eyes";
                    this.frightChain = Math.min(this.frightChain + 1, 4);
                    const pts = 100 * Math.pow(2, this.frightChain);
                    const mult = this.activePower?.type === "double" ? 2 : 1;
                    this._addScore(pts * mult);
                    this._popText(`+${pts * mult}`, e.col, e.row, "#7ee895");
                    audio.eatEnemy();
                } else {
                    if (this.activePower?.type === "shield") {
                        // burn shield instead of dying
                        this.activePower = null;
                        this._popText("SHIELD!", p.col, p.row, "#6cf2ff");
                        // briefly push enemy back
                        e.dir = OPP[e.dir];
                        audio.shieldHit();
                    } else {
                        this._loseLife();
                        return;
                    }
                }
            }
        }
    }

    _loseLife() {
        this.lives -= 1;
        audio.death();
        this.onLifeLost?.(this.lives);
        this.onLivesChange?.(this.lives);
        if (this.lives <= 0) {
            this.running = false;
            audio.stopMusic();
            this.onGameOver?.({ score: this.score, level: this.level });
            return;
        }
        // reset positions
        this.player.col = PLAYER_SPAWN.col;
        this.player.row = PLAYER_SPAWN.row;
        this.player.dir = "left";
        this.player.queued = null;
        for (let i = 0; i < this.enemies.length; i++) {
            const spawn = ENEMY_SPAWNS[i % ENEMY_SPAWNS.length];
            const e = this.enemies[i];
            e.col = spawn.col;
            e.row = spawn.row;
            e.state = "exit";
            e.exited = false;
            e.releaseAt = i * 1.0;
            e.dir = ["up", "left", "right"][i % 3];
        }
        this._readyTimer = 1.5;
        this.frightened = 0;
        this.activePower = null;
    }

    _nextLevel() {
        audio.levelUp();
        this.level += 1;
        this._initLevel();
        audio.startMusic(this.level);
    }

    _addScore(n) {
        this.score += n;
        this.onScoreChange?.(this.score);
    }

    _popText(text, col, row, color) {
        this._floatTexts.push({ text, col, row, color, life: 0.9 });
    }

    // ---------- Render ----------
    _render() {
        const ctx = this.ctx;
        const t = this.theme;
        const now = performance.now();
        const shakePx = this._screenShake > 0 ? this._screenShake * 8 : 0;
        const offsetX = shakePx ? (Math.random() - 0.5) * shakePx : 0;
        const offsetY = shakePx ? (Math.random() - 0.5) * shakePx : 0;

        ctx.clearRect(0, 0, CANVAS_W, CANVAS_H);
        const sky = ctx.createLinearGradient(0, 0, 0, CANVAS_H);
        sky.addColorStop(0, t.floorAlt);
        sky.addColorStop(1, t.bg);
        ctx.fillStyle = sky;
        ctx.fillRect(0, 0, CANVAS_W, CANVAS_H);

        ctx.save();
        ctx.translate(offsetX, offsetY);
        this._drawCityFloor(ctx, t);
        this._drawWalls(ctx, t);

        for (let r = 0; r < ROWS; r += 1) {
            for (let c = 0; c < COLS; c += 1) {
                const value = this.grid[r][c];
                if (value === T.PELLET || value === T.POWER) {
                    this._drawCash(ctx, c, r, value === T.POWER, t, now);
                }
            }
        }

        for (const powerUp of this._powerUpsActive) this._drawPowerUp(ctx, powerUp);

        for (const floatText of this._floatTexts) {
            ctx.save();
            ctx.fillStyle = floatText.color;
            ctx.shadowColor = floatText.color;
            ctx.shadowBlur = 10;
            ctx.font = "bold 15px 'IBM Plex Mono', monospace";
            ctx.textAlign = "center";
            ctx.globalAlpha = Math.min(1, floatText.life * 1.2);
            ctx.fillText(floatText.text, floatText.col * TILE + TILE / 2, floatText.row * TILE + TILE / 2);
            ctx.restore();
        }

        for (const enemy of this.enemies) this._drawEnemy(ctx, enemy);
        this._drawPlayer(ctx);
        ctx.restore();

        this._drawAtmosphere(ctx, t, now);

        if (this._readyTimer > 0) {
            const panel = ctx.createLinearGradient(0, CANVAS_H / 2 - 72, 0, CANVAS_H / 2 + 72);
            panel.addColorStop(0, "rgba(4,8,18,0)");
            panel.addColorStop(0.3, "rgba(4,8,18,0.78)");
            panel.addColorStop(0.7, "rgba(4,8,18,0.78)");
            panel.addColorStop(1, "rgba(4,8,18,0)");
            ctx.fillStyle = panel;
            ctx.fillRect(0, CANVAS_H / 2 - 72, CANVAS_W, 144);
            ctx.fillStyle = t.power;
            ctx.shadowColor = t.power;
            ctx.shadowBlur = 20;
            ctx.font = "48px 'VT323', monospace";
            ctx.textAlign = "center";
            ctx.fillText("CHASE THE BAG!", CANVAS_W / 2, CANVAS_H / 2 + 12);
            ctx.shadowBlur = 0;
            ctx.fillStyle = t.ink;
            ctx.font = "20px 'VT323', monospace";
            ctx.fillText(`LEVEL ${this.level} — ${t.name.toUpperCase()}`, CANVAS_W / 2, CANVAS_H / 2 - 32);
        }

        if (this.paused) {
            ctx.fillStyle = "rgba(3,6,14,0.76)";
            ctx.fillRect(0, 0, CANVAS_W, CANVAS_H);
            ctx.fillStyle = t.power;
            ctx.shadowColor = t.power;
            ctx.shadowBlur = 18;
            ctx.font = "52px 'VT323', monospace";
            ctx.textAlign = "center";
            ctx.fillText("PAUSED", CANVAS_W / 2, CANVAS_H / 2);
            ctx.shadowBlur = 0;
            ctx.fillStyle = t.ink;
            ctx.font = "18px 'VT323', monospace";
            ctx.fillText("Tap pause or press P to resume", CANVAS_W / 2, CANVAS_H / 2 + 30);
        }
        if (this._debugHud) this._drawDebugHud(ctx);
    }

    _drawCityFloor(ctx, t) {
        for (let r = 0; r < ROWS; r += 1) {
            for (let c = 0; c < COLS; c += 1) {
                if (this.grid[r][c] === T.WALL) continue;
                const x = c * TILE;
                const y = r * TILE;
                const tile = ctx.createLinearGradient(x, y, x, y + TILE);
                tile.addColorStop(0, (r + c) % 2 === 0 ? t.floorAlt : t.floor);
                tile.addColorStop(1, t.bg);
                ctx.fillStyle = tile;
                ctx.fillRect(x, y, TILE, TILE);
                ctx.strokeStyle = "rgba(255,255,255,0.055)";
                ctx.strokeRect(x + 0.5, y + 0.5, TILE - 1, TILE - 1);
            }
        }
    }

    _drawCash(ctx, col, row, isPower, t, now) {
        const cx = col * TILE + TILE / 2;
        const cy = row * TILE + TILE / 2;
        const pulse = 0.72 + Math.sin(now / 170 + col) * 0.28;
        const width = isPower ? 16 : 10;
        const height = isPower ? 11 : 6;
        ctx.save();
        ctx.translate(cx, cy + (isPower ? Math.sin(now / 190 + col) * 1.5 : 0));
        ctx.shadowColor = isPower ? t.power : t.pellet;
        ctx.shadowBlur = isPower ? 18 * pulse : 8;
        ctx.fillStyle = isPower ? "#54f58a" : "#37db73";
        ctx.fillRect(-width / 2, -height / 2, width, height);
        ctx.fillStyle = "#baffcb";
        ctx.fillRect(-width / 2, -height / 2, width, 2);
        ctx.fillStyle = t.power;
        ctx.fillRect(-1.5, -height / 2, 3, height);
        if (isPower) {
            ctx.strokeStyle = "rgba(255,255,255,0.75)";
            ctx.lineWidth = 1;
            ctx.strokeRect(-width / 2, -height / 2, width, height);
        }
        ctx.restore();
    }

    _drawAtmosphere(ctx, t, now) {
        ctx.save();
        const vignette = ctx.createRadialGradient(CANVAS_W / 2, CANVAS_H / 2, 90, CANVAS_W / 2, CANVAS_H / 2, CANVAS_W * 0.7);
        vignette.addColorStop(0, "rgba(0,0,0,0)");
        vignette.addColorStop(1, "rgba(0,0,0,0.26)");
        ctx.fillStyle = vignette;
        ctx.fillRect(0, 0, CANVAS_W, CANVAS_H);

        const sweepY = (now / 9) % (CANVAS_H + 40) - 40;
        const sweep = ctx.createLinearGradient(0, sweepY, 0, sweepY + 40);
        sweep.addColorStop(0, "rgba(255,255,255,0)");
        sweep.addColorStop(0.5, t.glow + "24");
        sweep.addColorStop(1, "rgba(255,255,255,0)");
        ctx.fillStyle = sweep;
        ctx.fillRect(0, sweepY, CANVAS_W, 40);
        ctx.restore();
    }

    _drawWalls(ctx, t) {
        for (let r = 0; r < ROWS; r += 1) {
            for (let c = 0; c < COLS; c += 1) {
                if (this.grid[r][c] !== T.WALL) continue;
                const x = c * TILE;
                const y = r * TILE;
                const face = ctx.createLinearGradient(x, y, x + TILE, y + TILE);
                face.addColorStop(0, t.wallEdge);
                face.addColorStop(0.22, t.wall);
                face.addColorStop(1, t.wallShadow || t.bg);
                ctx.fillStyle = face;
                ctx.fillRect(x + 1, y + 1, TILE - 2, TILE - 2);

                ctx.fillStyle = "rgba(255,255,255,0.28)";
                ctx.fillRect(x + 2, y + 2, TILE - 4, 2);
                ctx.fillRect(x + 2, y + 2, 2, TILE - 4);
                ctx.fillStyle = "rgba(0,0,0,0.42)";
                ctx.fillRect(x + 3, y + TILE - 4, TILE - 4, 3);
                ctx.fillRect(x + TILE - 4, y + 3, 3, TILE - 4);

                if ((r * COLS + c) % 7 === 0) {
                    ctx.fillStyle = t.glow;
                    ctx.globalAlpha = 0.32;
                    ctx.fillRect(x + 5, y + 7, TILE - 10, 2);
                    ctx.globalAlpha = 1;
                }
            }
        }
    }

    _pickPowerUpType() {
        const types = POWERUP_TYPES.filter((type) => POWERUP_WEIGHTS[type] > 0);
        if (!types.length) return POWERUP_TYPES[0];
        const totalWeight = types.reduce((sum, type) => sum + POWERUP_WEIGHTS[type], 0);
        let roll = Math.random() * totalWeight;
        for (const type of types) {
            roll -= POWERUP_WEIGHTS[type];
            if (roll <= 0) return type;
        }
        return types[types.length - 1];
    }

    _drawDebugHud(ctx) {
        const active = this.activePower ? `${this.activePower.type}:${this.activePower.time.toFixed(1)}s` : "none";
        const lines = [
            `DEBUG`,
            `Power: ${active}`,
            `Lives: ${this.lives}`,
            `Bomb wipe: ${this._lastBombWipe}`,
            `Shake: ${this._screenShake.toFixed(2)}s`,
            `On-map: ${this._powerUpsActive.map((p) => p.type).join(", ") || "none"}`,
        ];
        ctx.save();
        ctx.globalAlpha = 0.9;
        ctx.fillStyle = "rgba(0,0,0,0.65)";
        ctx.fillRect(10, 10, 260, 118);
        ctx.globalAlpha = 1;
        ctx.fillStyle = "#7df5e2";
        ctx.font = "14px 'IBM Plex Mono', monospace";
        for (let i = 0; i < lines.length; i++) {
            ctx.fillText(lines[i], 18, 30 + i * 16);
        }
        ctx.restore();
    }

    _drawPowerUp(ctx, pu) {
        const cx = pu.col * TILE + TILE / 2;
        const cy = pu.row * TILE + TILE / 2;
        const wob = Math.sin(performance.now() / 200 + pu.col) * 1.5;
        const pulse = 0.6 + Math.sin(performance.now() / 200 + pu.col) * 0.4;
        ctx.save();
        ctx.translate(cx, cy + wob);
        if (pu.type === "speed") {
            ctx.fillStyle = "#ffd84a";
            ctx.shadowColor = "#ffd84a";
            ctx.shadowBlur = 14 * pulse;
            // lightning bolt
            ctx.beginPath();
            ctx.moveTo(-3, -7); ctx.lineTo(3, -2); ctx.lineTo(-1, -1);
            ctx.lineTo(3, 7);   ctx.lineTo(-3, 2); ctx.lineTo(1, 1);
            ctx.closePath();
            ctx.fill();
        } else if (pu.type === "shield") {
            ctx.fillStyle = "#6cf2ff";
            ctx.shadowColor = "#6cf2ff";
            ctx.shadowBlur = 14 * pulse;
            ctx.beginPath();
            ctx.moveTo(0, -8);
            ctx.lineTo(7, -4); ctx.lineTo(7, 3);
            ctx.lineTo(0, 8);
            ctx.lineTo(-7, 3); ctx.lineTo(-7, -4);
            ctx.closePath(); ctx.fill();
            ctx.fillStyle = "rgba(255,255,255,0.45)";
            ctx.beginPath();
            ctx.arc(-2, -2, 2.2, 0, Math.PI * 2); ctx.fill();
        } else if (pu.type === "double") {
            ctx.fillStyle = "#d36cff";
            ctx.shadowColor = "#d36cff";
            ctx.shadowBlur = 14 * pulse;
            ctx.font = "bold 13px 'IBM Plex Mono', monospace";
            ctx.textAlign = "center";
            ctx.textBaseline = "middle";
            ctx.fillText("x2", 0, 0);
        } else if (pu.type === "bomb") {
            ctx.shadowColor = "#ff6b3a";
            ctx.shadowBlur = 18 * pulse;
            ctx.fillStyle = "#222";
            ctx.beginPath();
            ctx.arc(0, 1, 6, 0, Math.PI * 2);
            ctx.fill();
            ctx.strokeStyle = "#ff6b3a";
            ctx.lineWidth = 1.6;
            ctx.beginPath();
            ctx.arc(0, 1, 6, 0, Math.PI * 2);
            ctx.stroke();
            ctx.strokeStyle = "#ffd84a";
            ctx.lineWidth = 1.5;
            ctx.beginPath();
            ctx.moveTo(0, -5);
            ctx.quadraticCurveTo(3, -8, 5, -10);
            ctx.stroke();
            ctx.fillStyle = "#fff5c8";
            ctx.beginPath();
            ctx.arc(5, -10, 1.6, 0, Math.PI * 2);
            ctx.fill();
        } else if (pu.type === "life") {
            ctx.shadowColor = "#ff5577";
            ctx.shadowBlur = 18 * pulse;
            ctx.fillStyle = "#ff5577";
            ctx.beginPath();
            ctx.moveTo(0, 6);
            ctx.bezierCurveTo(-9, -1, -6, -9, 0, -4);
            ctx.bezierCurveTo(6, -9, 9, -1, 0, 6);
            ctx.closePath();
            ctx.fill();
            ctx.fillStyle = "rgba(255,255,255,0.55)";
            ctx.beginPath();
            ctx.arc(-2.5, -3, 1.6, 0, Math.PI * 2);
            ctx.fill();
        }
        ctx.shadowBlur = 0;
        ctx.restore();
    }

    _drawScanlines(ctx) {
        ctx.save();
        const t = performance.now();
        for (let y = 0; y < CANVAS_H; y += 3) {
            ctx.fillStyle = "rgba(0, 0, 0, 0.08)";
            ctx.fillRect(0, y, CANVAS_W, 1);
        }
        const sweepY = (t / 6) % (CANVAS_H + 24) - 24;
        const grad = ctx.createLinearGradient(0, sweepY, 0, sweepY + 24);
        grad.addColorStop(0, "rgba(120,255,240,0)");
        grad.addColorStop(0.5, "rgba(120,255,240,0.18)");
        grad.addColorStop(1, "rgba(120,255,240,0)");
        ctx.fillStyle = grad;
        ctx.fillRect(0, sweepY, CANVAS_W, 24);
        ctx.restore();
    }

    _drawEnemy(ctx, e) {
        const cx = e.col * TILE + TILE / 2;
        const cy = e.row * TILE + TILE / 2;
        const dir = DIRS[e.dir];

        // Eyes-only (defeated, returning home)
        if (e.state === "eyes") {
            ctx.fillStyle = "#fff";
            ctx.beginPath();
            ctx.arc(cx - 4, cy - 1, 3, 0, Math.PI * 2);
            ctx.arc(cx + 4, cy - 1, 3, 0, Math.PI * 2);
            ctx.fill();
            ctx.fillStyle = "#000";
            ctx.beginPath();
            ctx.arc(cx - 4 + dir.dc * 1.5, cy - 1 + dir.dr * 1.5, 1.4, 0, Math.PI * 2);
            ctx.arc(cx + 4 + dir.dc * 1.5, cy - 1 + dir.dr * 1.5, 1.4, 0, Math.PI * 2);
            ctx.fill();
            return;
        }

        // Body palette
        let shirt, pant = "#0a0a14", skin = "#d4a373";
        if (e.state === "fright") {
            const blink = this.frightened < 2 && Math.floor(performance.now() / 200) % 2 === 0;
            shirt = blink ? "#f5f1e8" : "#23308a";
            pant  = blink ? "#cccccc" : "#171f5a";
            skin  = blink ? "#f5f1e8" : "#23308a";
        } else if (e.type === "cop") {
            shirt = "#1e3b75";
            pant  = "#0a1438";
        } else {
            shirt = "#5a1010";
            pant  = "#1a0808";
        }

        const phase = (e.col + e.row) * 1.7 + performance.now() / 110;
        const swA = Math.sin(phase) * 3;
        const swB = Math.sin(phase + Math.PI) * 3;

        ctx.save();
        ctx.translate(cx, cy);
        if (dir.dc < 0) ctx.scale(-1, 1);

        // Legs
        ctx.fillStyle = pant;
        ctx.fillRect(-3, 3, 2.4, 6 + swA / 2);
        ctx.fillRect(0.6, 3, 2.4, 6 + swB / 2);
        // Shoes
        ctx.fillStyle = "#000";
        ctx.fillRect(-3.4, 8 + swA / 2, 3.2, 1.5);
        ctx.fillRect(0.2, 8 + swB / 2, 3.2, 1.5);

        // Torso
        ctx.fillStyle = shirt;
        ctx.fillRect(-4, -4, 8, 8);

        // Arms
        ctx.fillStyle = shirt;
        ctx.fillRect(-5.5, -3, 2, 5 + swB / 2);
        ctx.fillRect(3.5, -3, 2, 5 + swA / 2);
        ctx.fillStyle = skin;
        ctx.fillRect(-5.5, 2 + swB / 2, 2, 1.5);
        ctx.fillRect(3.5, 2 + swA / 2, 2, 1.5);

        // Head
        ctx.fillStyle = skin;
        ctx.beginPath();
        ctx.arc(0, -7, 3.6, 0, Math.PI * 2);
        ctx.fill();

        // Eye
        ctx.fillStyle = "#000";
        ctx.fillRect(0.8, -8, 1.4, 1.4);

        // Headwear / accessories
        if (e.state === "fright") {
            ctx.fillStyle = "#000";
            ctx.fillRect(-1.4, -5.4, 2.6, 0.9);
        } else if (e.type === "cop") {
            ctx.fillStyle = "#0a1438";
            ctx.fillRect(-4, -10.2, 8, 2.6);
            ctx.fillRect(-5.6, -8, 3, 1.2);
            ctx.fillStyle = "#ffd84a";
            ctx.fillRect(-0.8, -9.6, 1.6, 1.4);
            ctx.fillStyle = "#ffd84a";
            ctx.fillRect(-0.8, -1, 1.6, 1.6);
        } else {
            // Thug — hood
            ctx.fillStyle = "#161616";
            ctx.beginPath();
            ctx.arc(0, -7, 4.6, Math.PI * 1.05, Math.PI * 1.95);
            ctx.fill();
            ctx.fillRect(-4.6, -8, 9.2, 2.2);
            // bandana
            ctx.fillStyle = "#3a3a3a";
            ctx.fillRect(-3.6, -5.6, 7.2, 1.4);
        }

        ctx.restore();
    }

    _drawPlayer(ctx) {
        const p = this.player;
        const cx = p.col * TILE + TILE / 2;
        const cy = p.row * TILE + TILE / 2;
        const dir = DIRS[p.dir];

        if (this.activePower?.type === "shield") {
            ctx.strokeStyle = "rgba(108, 242, 255, 0.85)";
            ctx.lineWidth = 2;
            const radius = 16 + Math.sin(performance.now() / 100) * 1.5;
            ctx.beginPath();
            ctx.arc(cx, cy, radius, 0, Math.PI * 2);
            ctx.stroke();
        }
        if (this.activePower?.type === "speed") {
            ctx.strokeStyle = "rgba(255, 216, 74, 0.85)";
            ctx.lineWidth = 2;
            for (let i = 0; i < 3; i += 1) {
                ctx.beginPath();
                ctx.moveTo(cx - dir.dc * (10 + i * 4), cy - dir.dr * (10 + i * 4) - 3);
                ctx.lineTo(cx - dir.dc * (14 + i * 4), cy - dir.dr * (14 + i * 4) - 3);
                ctx.stroke();
            }
        }
        if (this.activePower?.type === "double") {
            ctx.fillStyle = "#d36cff";
            ctx.font = "bold 10px 'IBM Plex Mono', monospace";
            ctx.textAlign = "center";
            ctx.fillText("x2", cx + 12, cy - 12);
        }

        const sprite = getPlayerSprite(this.character);
        const phase = (p.col + p.row) * 1.9 + performance.now() / 90;
        const bob = Math.sin(phase) * 1.2;
        if (sprite) {
            const scale = 34 / Math.max(sprite.width, sprite.height);
            const width = sprite.width * scale;
            const height = sprite.height * scale;
            ctx.save();
            ctx.translate(cx, cy + bob);
            if (dir.dc < 0) ctx.scale(-1, 1);
            ctx.drawImage(sprite, -width / 2, -height / 2, width, height);
            ctx.restore();
        } else {
            ctx.fillStyle = this.character === "girl" ? "#ff3ec8" : "#e0413a";
            ctx.beginPath();
            ctx.arc(cx, cy + bob, 8, 0, Math.PI * 2);
            ctx.fill();
        }
    }
}
