import { useCallback, useEffect, useMemo, useState } from "react";
import {
    COOL_POINTS_STORAGE_KEY,
    COOL_POINTS_SOURCES,
    getProgressForPoints,
} from "./coolPointsConfig";

const COOL_POINTS_SYNC_EVENT = "hyphsworld:cool-points-sync";

const DEFAULT_STATE = {
    balance: 0,
    lifetimeEarned: 0,
    lifetimeSpent: 0,
    streakCount: 0,
    lastDailyClaimAt: null,
    unlockedRewards: [],
    badges: [],
    transactions: [],
};

function nowStamp() {
    return new Date().toISOString();
}

function createTransaction({ type, amount, source, reason }) {
    return {
        id: `${Date.now()}-${Math.random().toString(16).slice(2)}`,
        type,
        amount,
        source,
        sourceLabel: COOL_POINTS_SOURCES[source] || source || "HyphsWorld",
        reason,
        createdAt: nowStamp(),
    };
}

function loadState() {
    if (typeof window === "undefined") {
        return DEFAULT_STATE;
    }

    try {
        const raw = window.localStorage.getItem(COOL_POINTS_STORAGE_KEY);
        if (!raw) {
            return DEFAULT_STATE;
        }

        return {
            ...DEFAULT_STATE,
            ...JSON.parse(raw),
        };
    } catch (error) {
        console.warn("Cool Points state could not be loaded", error);
        return DEFAULT_STATE;
    }
}

function saveState(nextState) {
    if (typeof window === "undefined") {
        return;
    }

    window.localStorage.setItem(COOL_POINTS_STORAGE_KEY, JSON.stringify(nextState));
    window.dispatchEvent(new CustomEvent(COOL_POINTS_SYNC_EVENT, { detail: nextState }));
}

export function useCoolPoints() {
    const [state, setState] = useState(loadState);

    useEffect(() => {
        if (typeof window === "undefined") {
            return undefined;
        }

        const handleStateSync = (event) => {
            const nextState = event?.detail || loadState();
            setState((current) => ({ ...current, ...nextState }));
        };

        const handleStorage = (event) => {
            if (event.key && event.key !== COOL_POINTS_STORAGE_KEY) {
                return;
            }
            setState(loadState());
        };

        window.addEventListener(COOL_POINTS_SYNC_EVENT, handleStateSync);
        window.addEventListener("storage", handleStorage);

        return () => {
            window.removeEventListener(COOL_POINTS_SYNC_EVENT, handleStateSync);
            window.removeEventListener("storage", handleStorage);
        };
    }, []);

    const commitState = useCallback((updater) => {
        setState((current) => {
            const nextState = typeof updater === "function" ? updater(current) : updater;
            saveState(nextState);
            return nextState;
        });
    }, []);

    const earnCoolPoints = useCallback(({ amount, source = "homepage", reason = "Cool Points earned" }) => {
        const safeAmount = Math.max(0, Number(amount) || 0);
        if (!safeAmount) {
            return;
        }

        commitState((current) => {
            const transaction = createTransaction({
                type: "earn",
                amount: safeAmount,
                source,
                reason,
            });

            return {
                ...current,
                balance: current.balance + safeAmount,
                lifetimeEarned: current.lifetimeEarned + safeAmount,
                transactions: [transaction, ...current.transactions].slice(0, 50),
            };
        });
    }, [commitState]);

    const spendCoolPoints = useCallback(({ amount, source = "lobby", reason = "Cool Points spent" }) => {
        const safeAmount = Math.max(0, Number(amount) || 0);
        if (!safeAmount) {
            return false;
        }

        let approved = false;

        commitState((current) => {
            if (current.balance < safeAmount) {
                approved = false;
                return current;
            }

            approved = true;
            const transaction = createTransaction({
                type: "spend",
                amount: safeAmount,
                source,
                reason,
            });

            return {
                ...current,
                balance: current.balance - safeAmount,
                lifetimeSpent: current.lifetimeSpent + safeAmount,
                transactions: [transaction, ...current.transactions].slice(0, 50),
            };
        });

        return approved;
    }, [commitState]);

    const adjustCoolPoints = useCallback(({ amount, source = "admin", reason = "Cool Points adjusted" }) => {
        const safeAmount = Number(amount) || 0;
        if (!safeAmount) {
            return;
        }

        commitState((current) => {
            const nextBalance = Math.max(0, current.balance + safeAmount);
            const transaction = createTransaction({
                type: "adjust",
                amount: safeAmount,
                source,
                reason,
            });

            return {
                ...current,
                balance: nextBalance,
                lifetimeEarned: safeAmount > 0 ? current.lifetimeEarned + safeAmount : current.lifetimeEarned,
                lifetimeSpent: safeAmount < 0 ? current.lifetimeSpent + Math.abs(safeAmount) : current.lifetimeSpent,
                transactions: [transaction, ...current.transactions].slice(0, 50),
            };
        });
    }, [commitState]);

    const resetLocalCoolPoints = useCallback(() => {
        commitState(DEFAULT_STATE);
    }, [commitState]);

    const progress = useMemo(() => getProgressForPoints(state.balance), [state.balance]);

    return {
        ...state,
        progress,
        currentLevel: progress.currentLevel,
        nextLevel: progress.nextLevel,
        earnCoolPoints,
        spendCoolPoints,
        adjustCoolPoints,
        resetLocalCoolPoints,
    };
}
